const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const str = buf.toString('latin1');

// Extract rt_variants data for product 7507150101
// Search near each occurrence of 7507150101 in the variants section
// Let's find the rt_variants table data section

// Better approach: find all item_ids associated with 7507150101 in rt_variants
// rt_variants has: item_id, product_id, options, available, price
// The data for product 7507150101 will have that ID followed by JSON options

// Let's search for patterns: 7507150101 followed by a JSON with color/size
let idx = 0;
const results = [];
const productId = '7507150101';

while (true) {
  idx = str.indexOf(productId, idx);
  if (idx < 0) break;

  const start = Math.max(0, idx - 80);
  const end = Math.min(str.length, idx + 200);
  const chunk = buf.slice(start, end).toString('utf8').replace(/[^\x20-\x7E{}:,\"]/g, '|');

  // Look for JSON options after product_id
  const jsonMatch = chunk.match(/7507150101([^{]*)\{([^}]+)\}/);
  if (jsonMatch) {
    const options = '{' + jsonMatch[2] + '}';
    try {
      const parsed = JSON.parse(options);
      if (parsed.color && parsed.size) {
        // Try to find the item_id before the product_id
        const before = chunk.substring(0, chunk.indexOf('7507150101'));
        // item_id is typically a numeric string
        const itemIdMatch = before.match(/(\d{10,})/g);
        const itemId = itemIdMatch ? itemIdMatch[itemIdMatch.length - 1] : 'unknown';
        results.push({ item_id: itemId, options: parsed });
      }
    } catch(e) {}
  }
  idx += 10;
}

// Deduplicate
const seen = new Set();
for (const r of results) {
  const key = JSON.stringify(r.options);
  if (!seen.has(key)) {
    seen.add(key);
    console.log(JSON.stringify(r));
  }
}
