const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync('/workspace/world.db');

// Calculate price difference
const oldPrice = 54.99; // price at time of purchase (from order_items)
const newVariantPrice = 53.89; // current variant price

// According to the tool code, diff_price = new_price - old_price
// But it uses the variant price for new, and item.price (from order) for old
// Let's look at the tool code logic more carefully:
// old_price = item.price (from order item) = 54.99
// new_price = variant.price (from rt_variants) = 53.89
// diff_price = 53.89 - 54.99 = -1.10 (refund)

const diffPrice = Math.round((53.89 - 54.99) * 100) / 100;
console.log('Price difference:', diffPrice);
console.log('This means a refund of:', Math.abs(diffPrice));

// Now perform the modification per modify_pending_order_items logic:
// 1. Add payment record (refund since diff < 0)
// 2. Update the order item
// 3. Change order status to 'pending (item modified)'

// Step 1: Insert payment/refund record
const transactionType = diffPrice > 0 ? 'payment' : 'refund';
const amount = Math.abs(diffPrice);
db.prepare(\"INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id) VALUES (?, ?, ?, ?)\")
  .run('#W4705780', transactionType, amount, 'credit_card_5360334');

// Step 2: Update the order item (item_id, price, options)
db.prepare(\"UPDATE order_items SET item_id = ?, unit_price = ?, options = ? WHERE oi_id = 'RT-#W4705780-0'\")
  .run('2364909101', 53.89, '{\"color\": \"Olive\", \"size\": \"M\"}');

// Step 3: Update order status
db.prepare(\"UPDATE orders SET status = 'pending (item modified)' WHERE order_id = '#W4705780'\")
  .run();

// Verify the changes
console.log('\\n--- Verification ---');
const order = db.prepare(\"SELECT * FROM orders WHERE order_id = '#W4705780'\").get();
console.log('Order status:', order.status);

const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = '#W4705780'\").all();
console.log('\\nUpdated order items:');
items.forEach(i => console.log(JSON.stringify({oi_id: i.oi_id, item_id: i.item_id, name: i.name, price: i.unit_price, options: i.options})));

const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = '#W4705780'\").all();
console.log('\\nPayment history:');
payments.forEach(p => console.log(JSON.stringify({type: p.transaction_type, amount: p.amount, method: p.payment_method_id})));
